mapper.select:
SELECT id AS binding_id, provider_id, notification_code AS code, route,
       language_tag, sign_name, provider_template_code,
       parameter_mapping::text AS parameter_mapping_json, enabled, version
FROM notification_sms_binding
WHERE deleted = 0
AND id = #{bindingId}
AND provider_id = #{providerId}
AND notification_code = #{notificationCode}
AND route = #{route}
AND language_tag = #{languageTag}
AND enabled = #{enabled}
ORDER BY id

mapper.update:
UPDATE notification_sms_provider
SET enabled = #{enabled}, version = version + 1
WHERE id = #{providerId} AND deleted = 0 AND version = #{expectedVersion}

UPDATE notification_sms_binding
SET enabled = #{enabled}, version = version + 1
WHERE id = #{bindingId} AND deleted = 0 AND version = #{expectedVersion}

UPDATE notification_sms_binding
SET deleted = 1, version = version + 1
WHERE id = #{bindingId} AND enabled = FALSE AND deleted = 0 AND version = #{expectedVersion}
